class TenantScope implements Scope {
    public function apply(Builder $builder, Model $model): void {
        if ($id = CurrentTenant::id()) $builder->where($model->qualifyColumn('tenant_id'), $id);
    }
}
trait BelongsToTenant {
    protected static function bootBelongsToTenant(): void {
        static::addGlobalScope(new TenantScope);
        static::creating(fn (Model $m) => $m->tenant_id ??= CurrentTenant::id());
    }
}
class Order extends Model { use BelongsToTenant; }

// prove
CurrentTenant::set(1); Order::count();            // only tenant 1
Order::withoutGlobalScope(TenantScope::class)->count();   // all
Order::create([...]);                              // tenant_id = 1 set automatically
// qualifyColumn matters: without it, a JOIN with another table having tenant_id gives 'ambiguous column'.

final class Money {
    public function __construct(public readonly int $minor, public readonly string $currency) {}
    public static function bdt(int $minor): self { return new self($minor, 'BDT'); }
    public function formatted(): string { return ($this->currency === 'BDT' ? '৳' : $this->currency.' ').number_format($this->minor / 100, 2); }
}
class MoneyCast implements CastsAttributes {
    public function get(Model $model, string $key, mixed $value, array $attributes): ?Money {
        return $value === null ? null : new Money((int) $value, $attributes['currency'] ?? 'BDT');
    }
    public function set(Model $model, string $key, mixed $value, array $attributes): array {
        if (!$value instanceof Money) throw new InvalidArgumentException('Money expected');
        return ['total_minor' => $value->minor, 'currency' => $value->currency];
    }
}
class Order extends Model { protected function casts(): array { return ['total' => MoneyCast::class]; } }
// Order::create(['total' => Money::bdt(25000)]) → total_minor = 25000, currency = 'BDT'
// $order->total->formatted() → '৳250.00'
